<!DOCTYPE html>
<html lang="ja">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <meta name="csrf-token" content="{{ csrf_token() }}">
  <title>Foodiex 管理パネル</title>
  <script src="/vendors/admin/tailwindcss.js?v=20261119"></script>
  <script src="/vendors/admin/react.production.min.js?v=20261119"></script>
  <script src="/vendors/admin/react-dom.production.min.js?v=20261119"></script>
  <script src="/vendors/admin/htm.umd.js?v=20261119"></script>
  <style>
    :root{font-family:'Plus Jakarta Sans','Noto Sans JP',sans-serif} body{margin:0;background:#F7F8FA;color:#111827}.card{background:#fff;border-radius:16px;box-shadow:0 2px 12px rgba(17,24,39,.05)}.fade{animation:f .25s ease}@keyframes f{from{opacity:0;transform:translateY(6px)}to{opacity:1}}
  </style>
</head>
<body><div id="root"></div>
<script>
@verbatim
const {useState,useEffect,useMemo}=React,h=htm.bind(React.createElement);
const O='#F46A25', G='#10B981', Y='#F59E0B', R='#EF4444';
const NAV=[['概要','▦','Overview'],['注文','🧾','Orders'],['配達','🚚','Delivery'],['レストラン','🏪','Restaurants'],['ドライバー','🛵','Drivers'],['顧客','👥','Customers'],['商品','🍔','Products'],['財務','💳','Financials'],['プロモ・割引','🏷️','Promo'],['クレーム','💬','Complaints'],['レポート','📊','Reports'],['設定','⚙️','Settings']];
const DRIVERS=[{id:1,name:'Omar Khaled',vehicle:'Motorbike',rating:4.9,deliveries:1240,balance:320,online:true},{id:2,name:'Youssef Adel',vehicle:'Bicycle',rating:4.7,deliveries:860,balance:150,online:true},{id:3,name:'Karim Samy',vehicle:'Motorbike',rating:4.8,deliveries:1022,balance:0,online:false},{id:4,name:'Mostafa Nabil',vehicle:'Car',rating:4.5,deliveries:540,balance:780,online:true},{id:5,name:'Hassan Ali',vehicle:'Motorbike',rating:4.6,deliveries:712,balance:95,online:false}];
const statusClass=s=>({Paid:'bg-emerald-100 text-emerald-700',Pending:'bg-gray-100 text-gray-600','COD Unsettled':'bg-amber-100 text-amber-700',Failed:'bg-red-100 text-red-600',Refunded:'bg-purple-100 text-purple-700'}[s]||'bg-gray-100 text-gray-600');

async function api(path,options={}){const r=await fetch(path,{credentials:'same-origin',headers:{'Accept':'application/json','Content-Type':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]')?.content||'',...(options.headers||{})},...options});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.message||d.errors?.email?.[0]||'Request failed');return d}

function Modal({title,onClose,children}){return h`<div className="fixed inset-0 z-50 bg-black/40 flex items-center justify-center p-4" onClick=${onClose}><div className="card w-full max-w-md p-6 fade" onClick=${e=>e.stopPropagation()}><div className="flex justify-between items-center mb-4"><h3 className="text-lg font-bold">${title}</h3><button onClick=${onClose} className="text-gray-400">✕</button></div>${children}</div></div>`}
function Badge({text}){return h`<span className=${'px-2.5 py-1 rounded-full text-xs font-semibold '+statusClass(text)}>${text}</span>`}
function Btn({children,onClick,danger=false,className=''}){return h`<button onClick=${onClick} className=${'px-4 py-2 rounded-full text-sm font-semibold transition hover:opacity-90 '+(danger?'bg-red-500 text-white':'bg-[#F46A25] text-white')+' '+className}>${children}</button>`}
function Table({heads,rows}){return h`<div className="overflow-x-auto"><table className="w-full text-sm text-left"><thead><tr className="text-gray-400 text-xs uppercase">${heads.map(x=>h`<th key=${x} className="py-3 pr-4 font-medium">${x}</th>`)}</tr></thead><tbody>${rows.map((r,i)=>h`<tr key=${i} className="border-t border-gray-100 hover:bg-orange-50/40">${r.map((c,j)=>h`<td key=${j} className="py-3 pr-4 whitespace-nowrap">${c}</td>`)}</tr>`)}</tbody></table></div>`}

function Login({onLogin,demo}){const [email,setEmail]=useState(''),[password,setPassword]=useState(''),[show,setShow]=useState(false),[remember,setRemember]=useState(true),[error,setError]=useState(''),[loading,setLoading]=useState(false);const submit=async(e)=>{e.preventDefault();setError('');setLoading(true);try{await fetch('/sanctum/csrf-cookie',{credentials:'same-origin'});const d=await api('/api/admin/login',{method:'POST',body:JSON.stringify({email,password,remember})});onLogin(d.user)}catch(x){setError(x.message)}finally{setLoading(false)}};return h`<div className="min-h-screen grid place-items-center p-4"><div className="card w-full max-w-md p-8 fade"><div className="text-2xl font-extrabold mb-1 text-[#F46A25]">🚚 Foodiex</div><h1 className="text-xl font-bold mb-1">管理者ログイン</h1><p className="text-sm text-gray-500 mb-6">Admin sign in</p>${error&&h`<div className="mb-4 rounded-xl bg-red-50 text-red-600 text-sm px-4 py-3">${error}</div>`}<form onSubmit=${submit}><label className="block text-sm font-semibold mb-2">Email</label><input type="email" required value=${email} onChange=${e=>setEmail(e.target.value)} className="w-full border border-gray-200 rounded-xl px-4 py-3 mb-4 outline-none focus:ring-2 ring-orange-300" placeholder="admin@foodiex.com"/><label className="block text-sm font-semibold mb-2">Password</label><div className="relative mb-4"><input type=${show?'text':'password'} required value=${password} onChange=${e=>setPassword(e.target.value)} className="w-full border border-gray-200 rounded-xl px-4 py-3 pr-20 outline-none focus:ring-2 ring-orange-300"/><button type="button" onClick=${()=>setShow(!show)} className="absolute right-3 top-3 text-xs text-gray-500">${show?'Hide':'Show'}</button></div><label className="flex items-center gap-2 text-sm text-gray-600 mb-5"><input type="checkbox" checked=${remember} onChange=${e=>setRemember(e.target.checked)}/>Remember me</label><button disabled=${loading} className="w-full rounded-full bg-[#F46A25] text-white py-3 font-bold">${loading?'ログイン中…':'ログイン'}</button></form><button onClick=${demo} className="w-full mt-3 rounded-full border border-orange-200 text-[#F46A25] py-3 font-bold">Demo Mode</button></div></div>`}

function Overview({orders}){const data=[['Success orders',854,G,'✓'],['Delayed orders',253,Y,'⏱'],['Canceled orders',326,R,'✕']];return h`<div className="fade"><h2 className="text-2xl font-bold mb-4">注文概要</h2><div className="grid sm:grid-cols-3 gap-4">${data.map(([l,n,c,i])=>h`<div key=${l} className="card p-5 flex justify-between"><div><div className="text-xs font-semibold">${l}</div><div className="text-3xl font-extrabold my-1" style=${{color:c}}>${n}</div><div className="text-xs text-gray-500">Orders</div></div><div className="w-11 h-11 rounded-full text-white grid place-items-center" style=${{background:c}}>${i}</div></div>`)}</div><div className="card p-6 mt-5"><h3 className="font-bold text-lg mb-4">Live Active Orders</h3><Table heads=${['Order','Customer','Restaurant','Driver','Amount','Status']} rows=${orders.slice(0,6).map(o=>[h`<b>${o.id}</b>`,o.customer,o.restaurant,o.driver,o.amount+' EGP',h`<Badge text=${o.status}/>`])}/></div></div>`}

function Orders({orders,setOrders,toast}){const [filter,setFilter]=useState('All');const list=orders.filter(o=>filter==='All'||o.status===filter);const drivers=['—','Omar Khaled','Youssef Adel','Karim Samy','Mostafa Nabil','Hassan Ali'];const update=async(o,key,value)=>{const patch=key==='status'?{status:value}:{driver:value};const next=orders.map(x=>x.id===o.id?({...x,...patch}):x);setOrders(next);try{await api('/api/admin/orders/'+encodeURIComponent(o.id.replace('#',''))+'/status',{method:'PATCH',body:JSON.stringify(patch)})}catch(e){toast(e.message)}};return h`<div className="fade"><div className="flex gap-2 flex-wrap mb-4">${['All','Pending','Preparing','On the Way','Delivered','Delayed','Canceled'].map(x=>h`<button onClick=${()=>setFilter(x)} key=${x} className=${'px-4 py-2 rounded-full text-sm font-semibold '+(filter===x?'bg-[#F46A25] text-white':'bg-white')}>${x}</button>`)}</div><div className="card p-6"><Table heads=${['Order','Customer','Restaurant','Driver','Amount','Status']} rows=${list.map(o=>[h`<b>${o.id}</b>`,o.customer,o.restaurant,h`<select value=${o.driver} onChange=${e=>update(o,'driver',e.target.value)} className="bg-gray-50 rounded-lg px-2 py-1">${drivers.map(d=>h`<option key=${d}>${d}</option>`)}</select>`,o.amount+' EGP',h`<select value=${o.status} onChange=${e=>update(o,'status',e.target.value)} className="rounded-full px-2 py-1 text-xs font-semibold">${['Pending','Preparing','On the Way','Delivered','Delayed','Canceled'].map(s=>h`<option key=${s}>${s}</option>`)}</select>`])}/></div></div>`}
function Financials({orders,setOrders,toast}){const [tab,setTab]=useState('Sales');const [filter,setFilter]=useState('All');const [payment,setPayment]=useState(null);const [reference,setReference]=useState('');const [note,setNote]=useState('');const [drivers,setDrivers]=useState(DRIVERS);const [settle,setSettle]=useState(null);const [handover,setHandover]=useState('');const gross=orders.reduce((s,o)=>s+o.amount,0),paid=orders.filter(o=>o.paymentStatus==='Paid').reduce((s,o)=>s+o.amount,0),pending=orders.filter(o=>['Pending','COD Unsettled'].includes(o.paymentStatus)).reduce((s,o)=>s+o.amount,0),refunded=0;const tx=orders.filter(o=>filter==='All'||o.paymentStatus===filter);const markPaid=async()=>{if(!payment)return;try{await api('/api/admin/payments/'+encodeURIComponent(payment.id.replace('#',''))+'/status',{method:'PATCH',body:JSON.stringify({status:'Paid',reference,note})});setOrders(orders.map(o=>o.id===payment.id?{...o,paymentStatus:'Paid'}:o));setPayment(null);setReference('');setNote('');toast('Payment updated')}catch(e){toast(e.message)}};const settleCash=async()=>{if(!settle)return;try{await api('/api/admin/drivers/'+settle.id+'/settle-cod',{method:'POST',body:JSON.stringify({amount:settle.balance,handover_reference:handover})});setDrivers(drivers.map(d=>d.id===settle.id?{...d,balance:0}:d));setSettle(null);setHandover('');toast('COD cash settled')}catch(e){toast(e.message)}};return h`<div className="fade"><div className="flex gap-2 mb-5">${[['Sales','Sales & Pending Payments'],['COD','Driver COD Settlements'],['Payouts','Restaurant Payouts']].map(([k,l])=>h`<button key=${k} onClick=${()=>setTab(k)} className=${'px-4 py-2 rounded-full text-sm font-semibold '+(tab===k?'bg-[#F46A25] text-white':'bg-white')}>${l}</button>`)}</div>${tab==='Sales'&&h`<div><div className="grid sm:grid-cols-2 xl:grid-cols-4 gap-4 mb-5">${[['Gross Sales',gross,G],['Collected Revenue',paid,G],['Pending / Unsettled',pending,Y],['Refunded Amount',refunded,R]].map(([l,v,c])=>h`<div key=${l} className="card p-5"><div className="text-xs text-gray-500">${l}</div><div className="text-2xl font-extrabold mt-1" style=${{color:c}}>${v} EGP</div></div>`)}</div><div className="flex gap-2 mb-3">${['All','Paid','Pending','COD Unsettled','Failed'].map(x=>h`<button key=${x} onClick=${()=>setFilter(x)} className=${'px-3 py-1.5 rounded-full text-xs font-semibold '+(filter===x?'bg-[#F46A25] text-white':'bg-white')}>${x}</button>`)}</div><div className="card p-6"><Table heads=${['Order ID','Customer','Payment Method','Amount','Status','Date','']} rows=${tx.map(o=>[h`<b>${o.id}</b>`,o.customer,o.payment,o.amount+' EGP',h`<Badge text=${o.paymentStatus}/>`,o.date,['Pending','COD Unsettled'].includes(o.paymentStatus)?h`<button onClick=${()=>setPayment(o)} className="text-[#F46A25] font-semibold">Update</button>`:'—'])}/></div></div>`}${tab==='COD'&&h`<div className="card p-6"><Table heads=${['Driver','Vehicle','COD Balance','Status','']} rows=${drivers.map(d=>[d.name,d.vehicle,h`<b className="text-[#F46A25]">${d.balance} EGP</b>`,d.online?'Online':'Offline',d.balance>0?h`<button onClick=${()=>setSettle(d)} className="text-[#F46A25] font-semibold">Settle Cash</button>`:'Settled'])}/></div>`}${tab==='Payouts'&&h`<div className="card p-6"><Table heads=${['Restaurant','Gross Sales','Commission','Payout','']} rows=${[['Burger House',1380],['Pizza Napoli',240],['Sushi Nile',410],['Grill Master',320]].map(([name,grossSales])=>{const commission=grossSales*.15,payout=grossSales-commission;return [name,grossSales+' EGP',commission+' EGP',payout+' EGP',h`<button onClick=${async()=>{try{await api('/api/admin/restaurants/'+encodeURIComponent(name)+'/payout',{method:'POST',body:JSON.stringify({gross_sales:grossSales,commission:15})});toast('Payout marked as sent')}catch(e){toast(e.message)}}} className="text-[#F46A25] font-semibold">Mark Payout Sent</button>`]})}/></div>`}${payment&&h`<${Modal} title=${'Update Payment · '+payment.id} onClose=${()=>setPayment(null)}><label className="block text-sm font-semibold mb-2">Status</label><div className="mb-3"><Badge text="Paid"/></div><label className="block text-sm font-semibold mb-2">Transaction / receipt reference</label><input value=${reference} onChange=${e=>setReference(e.target.value)} className="w-full border rounded-xl p-3 mb-3" placeholder="TRX-2026-001"/><label className="block text-sm font-semibold mb-2">Admin audit note</label><textarea value=${note} onChange=${e=>setNote(e.target.value)} className="w-full border rounded-xl p-3 h-24 mb-4"/><${Btn} onClick=${markPaid}>Mark as Paid</${Btn}></${Modal}>`}${settle&&h`<${Modal} title=${'Settle COD · '+settle.name} onClose=${()=>setSettle(null)}><div className="mb-4 text-sm">Pending cash: <b className="text-[#F46A25]">${settle.balance} EGP</b></div><label className="block text-sm font-semibold mb-2">Handover reference</label><input value=${handover} onChange=${e=>setHandover(e.target.value)} className="w-full border rounded-xl p-3 mb-4" placeholder="Optional reference"/><${Btn} onClick=${settleCash}>Confirm Handover</${Btn}></${Modal}>`}</div>`}

function Vendors({toast}){const [vendors,setVendors]=useState([{id:1,name:'Burger House',open:true},{id:2,name:'Pizza Napoli',open:true},{id:3,name:'Sushi Nile',open:false},{id:4,name:'Grill Master',open:true}]);const [products,setProducts]=useState([{id:1,name:'Classic Burger',vendor:'Burger House',price:85,inStock:true},{id:2,name:'Margherita',vendor:'Pizza Napoli',price:120,inStock:true},{id:3,name:'Salmon Roll',vendor:'Sushi Nile',price:210,inStock:false}]);const toggle=async(type,item)=>{try{if(type==='vendor'){await api('/api/admin/restaurants/'+item.id+'/toggle',{method:'PATCH',body:JSON.stringify({open:!item.open})});setVendors(vendors.map(v=>v.id===item.id?{...v,open:!v.open}:v))}else{await api('/api/admin/products/'+item.id+'/toggle',{method:'PATCH',body:JSON.stringify({in_stock:!item.inStock})});setProducts(products.map(p=>p.id===item.id?{...p,inStock:!p.inStock}:p))}}catch(e){toast(e.message)}};return h`<div className="fade grid xl:grid-cols-2 gap-5"><div className="card p-6"><h3 className="font-bold mb-3">レストラン / Restaurants</h3><Table heads=${['Name','Open']} rows=${vendors.map(v=>[v.name,h`<button onClick=${()=>toggle('vendor',v)} className=${'w-11 h-6 rounded-full p-0.5 '+(v.open?'bg-emerald-500':'bg-gray-300')}><span className=${'block w-5 h-5 bg-white rounded-full '+(v.open?'translate-x-5':'')}></span></button>`])}/></div><div className="card p-6"><h3 className="font-bold mb-3">商品 / Menu</h3><Table heads=${['Item','Vendor','Price','In stock']} rows=${products.map(p=>[p.name,p.vendor,p.price+' EGP',h`<button onClick=${()=>toggle('product',p)} className=${'w-11 h-6 rounded-full p-0.5 '+(p.inStock?'bg-emerald-500':'bg-gray-300')}><span className=${'block w-5 h-5 bg-white rounded-full '+(p.inStock?'translate-x-5':'')}></span></button>`])}/></div></div>`}

function MenuManager({toast}){const [products,setProducts]=useState([]),[modal,setModal]=useState(null),[name,setName]=useState(''),[price,setPrice]=useState(''),[category,setCategory]=useState('洋食'),[stock,setStock]=useState(true),[image,setImage]=useState('');const load=async()=>{try{const d=await api('/api/admin/menu');setProducts(d.products||[])}catch(e){toast(e.message)}};useEffect(()=>{load()},[]);const openAdd=()=>{setModal('add');setName('');setPrice('');setCategory('洋食');setStock(true);setImage('')};const openEdit=p=>{setModal(p);setName(p.name);setPrice(p.price);setCategory(p.category||'洋食');setStock(!!p.in_stock);setImage(p.image||'')};const save=async()=>{if(!name.trim()||Number(price)<1)return toast('料理名と価格を入力してください');try{const body={name:name.trim(),price:Number(price),category,restaurant:'NK-EATS',image:image.trim()||null,in_stock:stock};if(modal==='add'){await api('/api/admin/products',{method:'POST',body:JSON.stringify(body)})}else{await api('/api/admin/products/'+modal.id,{method:'PATCH',body:JSON.stringify(body)})}setModal(null);await load();toast(modal==='add'?'料理を追加しました':'料理を更新しました')}catch(e){toast(e.message)}};const toggle=async p=>{try{await api('/api/admin/products/'+p.id+'/toggle',{method:'PATCH',body:JSON.stringify({in_stock:!p.in_stock})});await load()}catch(e){toast(e.message)}};const remove=async p=>{if(!confirm(p.name+' を削除しますか？'))return;try{await api('/api/admin/products/'+p.id,{method:'DELETE'});await load();toast('料理を削除しました')}catch(e){toast(e.message)}};return h`<div className="fade card p-6"><div className="flex justify-between items-center mb-4"><h3 className="font-bold text-lg">商品 / Menu</h3><${Btn} onClick=${openAdd}>＋ 料理を追加</${Btn}></div><${Table} heads=${['料理','カテゴリー','価格','在庫','']} rows=${products.map(p=>[p.name,p.category||'—',p.price+' EGP',h`<button onClick=${()=>toggle(p)} className=${'w-11 h-6 rounded-full p-0.5 '+(p.in_stock?'bg-emerald-500':'bg-gray-300')}><span className=${'block w-5 h-5 bg-white rounded-full '+(p.in_stock?'translate-x-5':'')}></span></button>`,h`<div className="flex gap-3"><button onClick=${()=>openEdit(p)} className="text-[#F46A25] font-semibold">編集</button><button onClick=${()=>remove(p)} className="text-red-500 font-semibold">削除</button></div>`])}/>${modal&&h`<${Modal} title=${modal==='add'?'料理を追加':'料理を編集'} onClose=${()=>setModal(null)}><label className="block text-sm font-semibold mb-2">料理名</label><input value=${name} onChange=${e=>setName(e.target.value)} className="w-full border rounded-xl p-3 mb-3"/><label className="block text-sm font-semibold mb-2">価格（EGP）</label><input type="number" value=${price} onChange=${e=>setPrice(e.target.value)} className="w-full border rounded-xl p-3 mb-3"/><label className="block text-sm font-semibold mb-2">カテゴリー</label><input value=${category} onChange=${e=>setCategory(e.target.value)} className="w-full border rounded-xl p-3 mb-3"/><label className="block text-sm font-semibold mb-2">画像URL</label><input value=${image} onChange=${e=>setImage(e.target.value)} className="w-full border rounded-xl p-3 mb-3"/><label className="flex items-center gap-2 mb-4"><input type="checkbox" checked=${stock} onChange=${e=>setStock(e.target.checked)}/>在庫あり</label><${Btn} onClick=${save}>保存</${Btn}></${Modal}>`}</div>`}

function Complaints({toast}){const [tickets,setTickets]=useState([{id:'T-201',order:'#FX1045',issue:'Food arrived cold',status:'Open'},{id:'T-202',order:'#FX1043',issue:'Missing item: fries',status:'Open'}]);const [modal,setModal]=useState(null);const [reply,setReply]=useState('');const resolve=async(refund=false)=>{try{await api('/api/admin/complaints/'+modal.id.replace('T-','')+'/resolve',{method:'POST',body:JSON.stringify({reply,refund})});setTickets(tickets.map(t=>t.id===modal.id?{...t,status:'Resolved'}:t));setModal(null);setReply('');toast(refund?'Refund issued':'Reply sent')}catch(e){toast(e.message)}};return h`<div className="fade card p-6"><h3 className="font-bold mb-3">Support tickets</h3><Table heads=${['Ticket','Order','Issue','Status','']} rows=${tickets.map(t=>[t.id,t.order,t.issue,t.status,t.status==='Open'?h`<button onClick=${()=>setModal(t)} className="text-[#F46A25] font-semibold">Resolve</button>`:'—'])}/>${modal&&h`<${Modal} title=${'Resolve '+modal.id} onClose=${()=>setModal(null)}><p className="text-sm mb-3">${modal.issue} (${modal.order})</p><textarea value=${reply} onChange=${e=>setReply(e.target.value)} className="w-full border rounded-xl p-3 h-24 mb-3" placeholder="Quick reply..."/><div className="flex gap-2"><${Btn} onClick=${()=>resolve(false)}>Send reply</${Btn}><${Btn} onClick=${()=>resolve(true)} danger=${true}>Refund order</${Btn}></div></${Modal}>`}</div>`}

function Generic({name,toast}){const tables={Customers:{heads:['Customer','Orders','Spent'],rows:[['Sara Mahmoud',24,'4,310 EGP'],['Ali Hassan',18,'3,020 EGP']]},Drivers:{heads:['Driver','COD Balance','Status'],rows:DRIVERS.map(d=>[d.name,d.balance+' EGP',d.online?'Online':'Offline'])},Delivery:{heads:['Area','Orders','Percentage'],rows:[['Cairo',697,'48%'],['Mansoura',435,'30%'],['Alex',318,'22%']]},Settings:{heads:['Setting','Value'],rows:[['Delivery zones','Cairo, Mansoura, Alex'],['Base delivery fee','25 EGP'],['Platform commission','15%']]},Reports:{heads:['Report','Period'],rows:[['Sales summary','Nov 2026'],['Driver performance','Nov 2026']]},Promo:{heads:['Code','Description','Active'],rows:[['WELCOME20','20% off first order','Yes'],['FREESHIP','Free delivery > 200 EGP','Yes']]}};const d=tables[name]||tables.Customers;return h`<div className="fade card p-6"><h3 className="font-bold text-lg mb-3">${name}</h3><${Table} heads=${d.heads} rows=${d.rows}/></div>`}

function App(){const [authenticated,setAuthenticated]=useState(false),[demo,setDemo]=useState(false),[user,setUser]=useState(null),[view,setView]=useState('Overview'),[orders,setOrders]=useState([]),[stats,setStats]=useState({kpis:{},chart:{series:[]}}),[sidebar,setSidebar]=useState(false),[toastM,setToast]=useState('');const toast=m=>{setToast(m);setTimeout(()=>setToast(''),2400)};useEffect(()=>{api('/api/admin/me').then(d=>{if(d.authenticated){setAuthenticated(true);setUser(d.user);const refresh=()=>{api('/api/admin/dashboard-stats').then(setStats).catch(()=>{});api('/api/admin/orders').then(r=>setOrders(r.orders||[])).catch(()=>{})};refresh();const timer=setInterval(refresh,15000);window.__nkAdminTimer=timer}}).catch(()=>{})},[]);const logout=async()=>{if(!demo)try{await api('/api/admin/logout',{method:'POST',body:'{}'})}catch(e){ }setDemo(false);setAuthenticated(false);setUser(null)};if(!authenticated&&!demo)return h`<${Login} onLogin=${u=>{setUser(u);setAuthenticated(true)}} demo=${()=>setDemo(true)}/>`;const panel=view==='Overview'?h`<${LiveOverview} orders=${orders} stats=${stats}/>`:view==='Orders'?h`<${Orders} orders=${orders} setOrders=${setOrders} toast=${toast}/>`:view==='Financials'?h`<${LiveFinancials} orders=${orders} toast=${toast}/>`:view==='Restaurants'?h`<${Vendors} toast=${toast}/>`:view==='Products'?h`<${LiveMenuManager} toast=${toast}/>`:view==='Complaints'?h`<${Complaints} toast=${toast}/>`:h`<${Generic} name=${view} toast=${toast}/>`;return h`<div className="min-h-screen flex"><button onClick=${()=>setSidebar(true)} className="lg:hidden fixed top-3 left-3 z-30 bg-white rounded-lg px-3 py-2 shadow">☰</button>${sidebar&&h`<div onClick=${()=>setSidebar(false)} className="fixed inset-0 z-30 bg-black/30 lg:hidden"></div>`}<aside className=${'fixed z-40 inset-y-0 left-0 w-60 bg-white flex flex-col transition-transform lg:translate-x-0 '+(sidebar?'':'-translate-x-full')}><div className="px-6 py-6 text-2xl font-extrabold text-[#F46A25]">🚚 Foodiex</div><div className="px-6 text-xs text-gray-400 mb-2">MAIN</div><nav className="flex-1 overflow-y-auto">${NAV.map(([label,icon,key])=>h`<button key=${key} onClick=${()=>{setView(key);setSidebar(false)}} className=${'w-full px-6 py-3 text-left flex gap-3 items-center text-sm '+(view===key?'bg-orange-50 text-[#F46A25] border-r-4 border-[#F46A25]':'text-gray-600')}> <span>${icon}</span><span>${label}</span></button>`)}</nav><button onClick=${logout} className="m-4 px-4 py-3 rounded-xl bg-gray-100 text-sm font-semibold">Logout</button></aside><main className="lg:ml-60 flex-1 p-5 lg:p-8">${panel}</main>${toastM&&h`<div className="fixed bottom-5 right-5 bg-gray-900 text-white px-4 py-3 rounded-xl shadow-lg">${toastM}</div>`}</div>`}
ReactDOM.createRoot(document.getElementById('root')).render(h`<${App}/>`);
@endverbatim
</script></body></html>
